/**
 * Tool - 工具基础类
 * 单独导出避免循环依赖
 */
export class Tool {
  constructor({ id, name, description, icon, execute, validate }) {
    this.id = id;
    this.name = name;
    this.description = description;
    this.icon = icon || '🔧';
    this.execute = execute;
    this.validate = validate || (() => ({ valid: true }));
  }
}