/**
 * Tool Registry - 工具注册中心
 * 基于 nanobot-design Tool System 架构
 * 单例模式，支持内置工具和自定义工具注册
 */
import { Tool } from './Tool.js';

// 延迟加载所有工具模块
const toolModules = [
  import('./wordCount.js'),
  import('./styleTag.js'),
  import('./qualityCheck.js'),
  import('./formatConvert.js'),
  import('./rhymeSearch.js'),
  import('./synonymSearch.js'),
  import('./punctuationCheck.js'),
  import('./charCount.js'),
];

class ToolRegistry {
  constructor() {
    this.tools = new Map();
    this.listeners = new Set();
    this._initialized = false;
  }

  register(tool) {
    if (!(tool instanceof Tool)) {
      tool = new Tool(tool);
    }
    this.tools.set(tool.id, tool);
    this.notify('register', tool);
    return this;
  }

  unregister(toolId) {
    const tool = this.tools.get(toolId);
    if (tool) {
      this.tools.delete(toolId);
      this.notify('unregister', tool);
    }
    return this;
  }

  get(toolId) {
    return this.tools.get(toolId);
  }

  list() {
    return Array.from(this.tools.values());
  }

  execute(toolId, context) {
    const tool = this.tools.get(toolId);
    if (!tool) {
      return { success: false, error: `Tool ${toolId} not found` };
    }
    const validation = tool.validate(context);
    if (!validation.valid) {
      return { success: false, error: validation.error };
    }
    try {
      const result = tool.execute(context);
      return { success: true, result };
    } catch (e) {
      return { success: false, error: e.message };
    }
  }

  subscribe(listener) {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  notify(event, tool) {
    this.listeners.forEach(l => l(event, tool));
  }

  // 异步初始化所有工具
  async init() {
    if (this._initialized) return;
    this._initialized = true;
    const results = await Promise.all(toolModules);
    for (const mod of results) {
      const toolExport = Object.values(mod)[0];
      if (toolExport) {
        this.register(toolExport);
      }
    }
    console.log('[ToolRegistry] Initialized with', this.tools.size, 'tools');
  }
}

// Create singleton
export const toolRegistry = new ToolRegistry();

// Re-export Tool for backwards compatibility
export { Tool } from './Tool.js';

// 初始化工具注册表
toolRegistry.init();